    var xa = live(myIds).sort(sortNum), xb = live(oppIds).sort(sortNum);   // the eleven is a set
    if (xa.length !== 11 || xb.length !== 11) return res;
    var ba = live(myBench).filter(function (id) { return xa.indexOf(id) < 0; });
