  var xi = intOf(x, -1), yi = intOf(y, -1);
  if (xi === 0 && yi === 0) return Math.max(0, 1 - h * a * r);
  if (xi === 0 && yi === 1) return Math.max(0, 1 + h * r);
  if (xi === 1 && yi === 0) return Math.max(0, 1 + a * r);
  if (xi === 1 && yi === 1) return Math.max(0, 1 - r);
